/**
 * Ticket #29 acceptance test — grid alignment must not clip art that already fills its frame.
 * Do not edit this file to make it pass.
 */
import { describe, expect, it } from 'vitest';
import { fitCells, type FitCellsOptions } from '../../scripts/lib/gemini-art';
import type { PngImage } from '../../scripts/lib/png';

type Pixel = readonly [number, number, number, number];
const OUTLINE: Pixel = [20, 27, 27, 255];
const A: Pixel = [45, 105, 123, 255];
const B: Pixel = [184, 220, 229, 255];

/**
 * One 260 px cell holding a 240 × 240 full-bleed tile at (10, 10): a 10 px outline ring
 * (on the output grid at scale 1/10) around vertical stripes 10 px wide that start 5 px
 * off that grid, so the purity search prefers a 5 px offset — which would push the
 * 24 px piece one pixel past the 24 px frame.
 */
function tile(): PngImage {
  const size = 260;
  const data = Buffer.alloc(size * size * 4);
  for (let y = 10; y < 250; y += 1) {
    for (let x = 10; x < 250; x += 1) {
      const edge = x < 20 || x >= 240 || y < 20 || y >= 240;
      const colour = edge ? OUTLINE : Math.floor((x - 25 + 100) / 10) % 2 === 0 ? A : B;
      data.set(colour, (y * size + x) * 4);
    }
  }
  return { width: size, height: size, data };
}

const ICON: FitCellsOptions = { columns: 1, rows: 1, frameWidth: 24, frameHeight: 24, anchor: 'center', share: 'cell' };

function ringIsOutline(sheet: PngImage): boolean {
  for (let i = 0; i < 24; i += 1) {
    for (const [x, y] of [[i, 0], [i, 23], [0, i], [23, i]] as const) {
      const p = (y * sheet.width + x) * 4;
      for (let k = 0; k < 4; k += 1) if (sheet.data[p + k] !== OUTLINE[k]) return false;
    }
  }
  return true;
}

describe('#29 alignment never clips a full-frame piece', () => {
  it('fits the tile with its outline on all four edges without alignment', () => {
    expect(ringIsOutline(fitCells(tile(), ICON))).toBe(true);
  });

  it('keeps the outline on all four edges with alignment on', () => {
    expect(ringIsOutline(fitCells(tile(), { ...ICON, align: true }))).toBe(true);
  });

  it('gives the same pixels as without alignment, since no axis has room to shift', () => {
    const image = tile();
    expect(Buffer.compare(fitCells(image, { ...ICON, align: true }).data, fitCells(image, ICON).data)).toBe(0);
  });
});
